<script setup lang="ts">
import { onMounted,onUnmounted,ref,watch } from 'vue'
import { user,request } from '../services/auth'
import {pendingAction,startAction,retryAction,type Action} from '../services/orderLifecycle'
import { orderError } from '../services/orders'
import type { Order,OrderPage } from '../types/order'
const orders=ref<OrderPage>({items:[],page:1,size:20,total:0}),selected=ref<Order|null>(null),error=ref(''),busy=ref(false),expired=ref(false)
let sequence=0,timer:ReturnType<typeof setTimeout>|undefined,deadline=Date.now()+300000
const id=location.pathname.split('/')[2]
const reason=ref('用户申请取消未支付订单'),actionPending=ref<Action|null>(id?pendingAction(id,'cancel'):null)
async function cancel(original=false){if(!user.value||!selected.value||busy.value)return;const seq=sequence;busy.value=true;error.value='';try{const result=original&&actionPending.value?await retryAction<Order>(actionPending.value):await startAction<Order>(selected.value.orderId,'cancel',reason.value);if(seq===sequence){selected.value=result;actionPending.value=null;deadline=Date.now()+300000}}catch(e){if(seq===sequence)error.value=orderError(e)}finally{if(seq===sequence){actionPending.value=id?pendingAction(id,'cancel'):null;busy.value=false;schedule()}}}
function stop(){if(timer)clearTimeout(timer);timer=undefined}
function schedule(){stop();if(!id||document.hidden||Date.now()>=deadline||selected.value?.status!=='PROCESSING'&&selected.value?.status!=='CLOSING'){expired.value=Date.now()>=deadline;return}timer=setTimeout(()=>void load(),3000)}
async function load(page=orders.value.page){if(!user.value||busy.value)return;const owner=user.value.userId,seq=sequence;busy.value=true;error.value='';try{if(id){const o=await request<Order>('/orders/'+encodeURIComponent(id),owner);if(seq===sequence)selected.value=o}else{const p=await request<OrderPage>('/orders?page='+page+'&size=20',owner);if(seq===sequence)orders.value=p}}catch(e){if(seq===sequence)error.value=orderError(e)}finally{if(seq===sequence){busy.value=false;schedule()}}}
function visibility(){if(document.hidden)stop();else if(Date.now()<deadline)void load()}
watch(()=>user.value?.userId,()=>{sequence++;stop();actionPending.value=id?pendingAction(id,'cancel'):null;selected.value=null;orders.value={items:[],page:1,size:20,total:0};busy.value=false;deadline=Date.now()+300000;void load()})
onMounted(()=>{document.addEventListener('visibilitychange',visibility);void load()});onUnmounted(()=>{sequence++;stop();document.removeEventListener('visibilitychange',visibility)})
const status=(s:string)=>({PROCESSING:'处理中',WAITING_PAYMENT:'待支付',CLOSING:'关闭中',CLOSED:'已关闭'}[s]??s)
</script>
<template><section><h1>我的订单</h1><p v-if="!user">请登录后查看本人订单。<a href="/login?returnTo=/orders">去登录</a></p><template v-else><button :disabled="busy" @click="load()">刷新订单</button><p v-if="error" role="alert">{{error}}</p><p v-if="expired">自动查询已结束，可手动刷新。</p><article v-if="selected"><h2>{{selected.product.name}}</h2><p>订单 {{selected.orderId}} · {{status(selected.status)}}</p><p>¥ {{selected.offer.payPrice}} · 数量 {{selected.quantity}}</p><p>商品版本 {{selected.product.productVersion}} · {{selected.mode==='OPEN'?'开团':'加入指定团队'}}</p><p>创建于 {{new Date(selected.createdAt).toLocaleString()}}</p><p v-if="selected.status==='PROCESSING'">正在处理购买，请保留原订单编号。</p><p v-if="selected.reviewRequired" role="alert">订单需要后台核对，请保留原订单，不要重复购买。</p><p v-if="selected.errorCode&&!selected.reviewRequired">订单仍在核对，当前提示：{{selected.errorCode}}</p><template v-if="selected.teamId"><p>团队 {{selected.teamId}} · {{selected.aTeamStatus}}</p><a :href="'/teams/'+selected.teamId">查看团队与分享链接</a><p v-if="selected.paymentDeadline">A 确认的支付期限：{{new Date(selected.paymentDeadline).toLocaleString()}}</p></template><p v-if="selected.status==='CLOSING'">正在确认关闭，库存尚未释放；页面超时不代表关闭失败。</p><p v-if="selected.closedAt">关闭于 {{new Date(selected.closedAt).toLocaleString()}} · {{selected.closeBasis==='LOCAL_NEVER_DISPATCHED'?'请求未发出，已本地关闭':'A 已确认关闭'}}；库存已释放。</p><div v-if="actionPending"><p>取消结果待核对 · {{actionPending.body.operationId}}</p><button :disabled="busy" @click="cancel(true)">重试原取消</button></div><form v-else-if="selected.canCancel" @submit.prevent="cancel()"><label>取消原因<input v-model="reason" required maxlength="256" :disabled="busy"></label><button :disabled="busy">确认取消未支付订单</button></form><p>支付暂未开放。</p><a href="/orders">返回订单列表</a></article><template v-else><p v-if="!orders.items.length&&!busy">暂无订单。</p><article v-for="o in orders.items" :key="o.orderId"><h2>{{o.product.name}}</h2><p>{{status(o.status)}} · ¥ {{o.offer.payPrice}}</p><a :href="'/orders/'+o.orderId">查看订单</a></article><button :disabled="busy||orders.page<=1" @click="load(orders.page-1)">上一页</button><span>第 {{orders.page}} 页</span><button :disabled="busy||orders.page*orders.size>=orders.total" @click="load(orders.page+1)">下一页</button></template></template></section></template>
